function C = bdclp_config()
%BDCLP_CONFIG Independent, explicitly uncalibrated position-interface model.
% Manufacturer limits, study choices, and unknown device behaviour are separate.
C.schema = 'bdcl_position_execution_v1';
C.status = 'interface_constrained_simulation_not_hardware_identified';
C.study = 'bdcl_v29_20hz_two_method_r6_fix5';
C.clock = struct('plant_dt_s',.001,'control_dt_s',.05, ...
    'feedback_dt_s',.05,'power_dt_s',.01);
C.clock.assumption = '20 Hz external decisions; independent power acquisition; 1 ms numerical plant';
C.execution = struct('compute_mode','wall_time','budget_s',.005, ...
    'deadline_s',.05,'overrun_policy','hold_and_skip_busy_ticks');
C.execution.assumption = ['Formal evaluation schedules measured host decision computation; acquisition preprocessing is timed separately. ', ...
    'offline training uses the explicitly assumed 5 ms budget, not a hardware timing claim.'];
C.transport = struct('baud_rate',115200,'bits_per_byte',10, ...
    'command_processing_s',.010,'feedback_processing_s',.010,'power_delay_s',.002);
C.transport.assumption = ['Serial wire time is computed from encoded bytes; queueing is explicit. ', ...
    'Processing and independent power-sensor latency are uncalibrated study assumptions.'];
C.servo = bdclp_servo_defaults();
C.power = bdclp_power_defaults();
C.power.soft_budget_W = 12;
C.power.filter_tau_s = .05;
C.geometry = bdclp_geometry_defaults();
C.hardware = bdclp_interface_defaults();
C.command = struct('speed',floor(min(C.geometry.velocity_max_rad_s)*4096/(2*pi)), ...
    'acc',floor(min(C.geometry.acceleration_max_rad_s2)*4096/(200*pi)), ...
    'steps_per_turn',4096);
C.command.assumption = 'Shared SDK motion parameters; chosen study settings';
C.control = struct('rate_min',.15,'rate_max',1.2,'initial_rate',0, ...
    'rate_rise_per_s',6,'rate_fall_per_s',30, ...
    'feedback_gain_per_s',15,'tracking_pause_rad',.20, ...
    'preview_guard_enable',false,'guard_scales',[1 .5 0], ...
    'reference_samples',17,'reference_search_steps',12,'reference_limit_relative_tolerance',1e-9, ...
    'preview_extra_s',.01,'max_position_age_s',.08,'max_power_age_s',.04,'max_velocity_gap_s',.08);
C.observation = struct('position_quantum_rad',2*pi/4096, ...
    'position_noise_std_rad',1e-4, ...
    'power_noise_std_W',0,'voltage_noise_std_V',0);
C.observation.velocity_kind = 'filtered_difference_of_sampled_quantized_positions';
C.observation.velocity_filter_tau_s = .03;
C.task = struct('seed_train',13215,'seed_validation',53215,'seed_test',3215, ...
    'q0_jitter_rad',pi/180,'qf_jitter_rad',0, ...
    'payload_mass_edges_kg',[.12 .14 .16 .18], ...
    'payload_dimensions_m',[.256 .02 .02],'payload_com_m',[.128 0 0]);
C.evaluation = struct('N',100,'seed',3215,'noguard_rate',1.0,'initial_hold_s',1, ...
    'terminal_hold_s',.10,'position_tolerance_m',.015, ...
    'speed_tolerance_rad_s',.05,'max_time_s',20, ...
    'no_slower_tolerance_s',1e-9,'zero_excess_tolerance',1e-12);
C.evaluation.completion_schema = 'elapsed_reference_delivered_terminal_stable_v1';
C.readiness = struct('schema','physical_per_task_noslower_v28_v1', ...
    'require_all_valid',true,'max_mean_time_delta_s',1e-9, ...
    'max_mean_R_soft_delta',1e-12,'max_mean_excess_delta_W',1e-9, ...
    'max_mean_energy_delta_J',1e-9,'strict_time_improvement_s',1e-9, ...
    'strict_excess_improvement_W',1e-9,'strict_energy_improvement_J',1e-9);
C.learning = struct('seed',3215,'train_tasks',90,'validation_tasks',30, ...
    'rates',linspace(.15,1.2,8),'teacher_horizon_s',.20, ...
    'hidden_units',24,'epochs',150,'learning_rate',1e-4,'route_learning_rate',2e-3, ...
    'route_candidates',13,'route_prototypes',32,'route_proposals',5, ...
    'route_hidden_units',48,'batch_size',256,'patience',25,'l2',1e-5, ...
    'backend','transformer','sequence_length',5,'sequence_dt_s',.05, ...
    'd_model',128,'num_heads',4,'ffn_dim',256,'num_layers',2, ...
    'head_width',64,'ffn_activation','gelu','position_encoding','none', ...
    'dagger_rounds',1,'alternating_rounds',3, ...
    'route_noninferiority_tolerance_W',1e-9,'route_energy_tolerance_J',1e-9);
C.learning.method_schema='candidate_path_observed_rate_alternating_v28_v1';
C.learning.teacher_weights=struct('power',50,'progress',1, ...
    'tracking',.05,'smooth',.002,'reserve',.01,'terminal',.1);
C.learning.teacher_tracking_scale_rad=.05;
C.learning.teacher_velocity_scale_rad_s=.2;
C.learning.teacher_terminal_window_s=.1;
C.learning.terminal_objective_schema='shared_start_gate_reference_delivery_readiness_v1';
C.learning.teacher_progress_floor_rad_s=.02;
C.learning.teacher_tau_reserve_ratio=.97;
C.learning.teacher_reference_acc_reserve_ratio=.98;
C.learning.teacher_successor_search=struct( ...
    'schema','bounded_first_feasible_continuation_v1', ...
    'local_offsets',[-.02 -.005 -1e-5 0 1e-5 .005 .02], ...
    'refine_offsets',[-.05 -.02 -.01 -.005 -.002 -.001 -.0005 -.0002 -.0001 -.00005 -.00002 -.00001 -.000005 -.000002 -.000001 0 .000001 .000002 .000005 .00001 .00002 .00005 .0001 .0002 .0005 .001 .002 .005 .01 .02 .05], ...
    'grid_points',9,'transition_refine_iterations',7, ...
    'max_candidates',49,'max_parent_candidates',393);
C.learning.feedback_loss=struct('schema','delayed_position_response_regularized_v1', ...
    'mse_weight',1,'teacher_logit_weight',1,'physics_weight',1, ...
    'soft_power_weight',320,'speed_weight',.35,'endpoint_weight',.5, ...
    'support_weight',1,'rate_lower',C.control.rate_min,'rate_upper',C.control.rate_max, ...
    'response_horizon_s',.20,'response_schema','bdclp_delayed_first_action_response_v1');
C.learning.teacher_weight_scope='Prespecified development weights; no optimality or three-metric guarantee';
C.provenance = struct('source_release','bdcl_v28a16', ...
    'source_zip_sha256','1864ef0719c2e983ad5d41d5e693ba783431178a69539207f1748477963585b5', ...
    'execution_changed',true,'legacy_weights_compatible',false,'training_purpose','formal_study', ...
    'claim_scope',['20 Hz position-interface simulation; nominal NoGuard request 1.0 versus ', ...
    'Proposed up to 1.2; improvements include the different requested-rate ranges']);
bdclp_validate_config(C);
end
